-- Builds a study-note reader page from notes/<name>/index.qmd, a stub written
-- by scripts/build-note-sources.mjs whose `note-source` names the note's
-- Markdown or LaTeX file. The page gets the header generated by
-- scripts/render-static-content.mjs, a table of contents built from the
-- note's headings, and the note body.
--
-- LaTeX notes are read from the expanded copy in _generated/latex-notes/<name>/
-- and take their section, theorem, equation, and cross-reference numbers from
-- that folder's meta.json, which comes from compiling the note.

local CONTENTS_HEADINGS = { ["目录"] = true, ["contents"] = true, ["table of contents"] = true }
local TOC_LEVELS = { [2] = true, [3] = true }

-- Printed names for cleveref types that are not theorem-like environments.
local REFERENCE_NAMES = {
  part = "Part", section = "Section", subsection = "Section", subsubsection = "Section",
  appendix = "Appendix", equation = "Eq.", figure = "Figure", table = "Table",
  algocf = "Algorithm", algorithm = "Algorithm", lstlisting = "Listing",
  enumi = "Item", item = "Item", footnote = "Footnote"
}

-- Package macros that MathJax lacks, rewritten to equivalents.
local MATH_REWRITES = {
  { "\\bm%s*{", "\\boldsymbol{" },
  { "\\bm%s*\\", "\\boldsymbol\\" },
  { "\\mathbbm%s*{", "\\mathbb{" }
}

local function read_file(file)
  local handle = io.open(file, "r")
  if not handle then return nil end
  local content = handle:read("a")
  handle:close()
  return content
end

local function inlines_to_html(inlines)
  return pandoc.write(pandoc.Pandoc({ pandoc.Plain(inlines) }), "html"):gsub("\n", " ")
end

local function has_class(element, class)
  for _, name in ipairs(element.classes or {}) do
    if name == class then return true end
  end
  return false
end

-- A raw HTML block, or a paragraph made only of inline HTML such as <a id="x"></a>.
local function is_raw_html(block)
  if block.t == "RawBlock" then return true end
  if block.t ~= "Para" and block.t ~= "Plain" then return false end
  for _, inline in ipairs(block.content) do
    if inline.t ~= "RawInline" and inline.t ~= "Space" and inline.t ~= "SoftBreak" then return false end
  end
  return #block.content > 0
end

local function note_folder()
  return pandoc.path.make_relative(pandoc.path.directory(quarto.doc.input_file), quarto.project.directory)
end

local function load_page_data()
  local raw = read_file(pandoc.path.join({ quarto.project.directory, "_generated", "note-pages.json" }))
  if not raw then return {} end
  return quarto.json.decode(raw)[note_folder()] or {}
end

-- ---------------------------------------------------------------------------
-- Markdown notes

-- Notes write their caption as an italic line under each image ("*图 1：…*").
-- Use that line as the figure caption instead of the image's alt text.
local function merge_figure_captions(blocks)
  local merged = {}
  local i = 1
  while i <= #blocks do
    local block, next_block = blocks[i], blocks[i + 1]
    if block.t == "Figure" and next_block and next_block.t == "Para"
        and #next_block.content == 1 and next_block.content[1].t == "Emph" then
      local alt = pandoc.utils.stringify(block.caption.long)
      block = block:walk({
        Image = function(image)
          image.attributes["fig-alt"] = alt
          return image
        end
      })
      block.caption.long = { pandoc.Plain(next_block.content[1].content) }
      i = i + 1
    end
    table.insert(merged, block)
    i = i + 1
  end
  return merged
end

-- ---------------------------------------------------------------------------
-- LaTeX notes

-- Maps the heading levels in use onto h2, h3, h4, ... in order.
local function normalize_levels(doc)
  local used, levels = {}, {}
  doc:walk({ Header = function(h) used[h.level] = true end })
  for level in pairs(used) do table.insert(levels, level) end
  table.sort(levels)
  local target = {}
  for rank, level in ipairs(levels) do target[level] = math.min(rank + 1, 6) end
  return doc:walk({
    Header = function(h)
      h.level = target[h.level]
      return h
    end
  })
end

local function number_span(number)
  -- \part numbers are Roman numerals; LaTeX prints them as "Part I".
  if number:match("^[IVXLCDM]+$") then number = "Part " .. number end
  return pandoc.Span({ pandoc.Str(number) }, pandoc.Attr("", { "header-section-number" }))
end

local function number_sections(doc, numbers)
  if not numbers then return doc end
  local count = 0
  doc:walk({ Header = function(h) if not has_class(h, "unnumbered") then count = count + 1 end end })
  if count ~= #numbers then
    quarto.log.warning(string.format("note reader: %d numbered headings but %d section numbers", count, #numbers))
    return doc
  end
  local index = 0
  return doc:walk({
    Header = function(h)
      if has_class(h, "unnumbered") then return nil end
      index = index + 1
      h.content:insert(1, pandoc.Space())
      h.content:insert(1, number_span(numbers[index]))
      return h
    end
  })
end

-- Theorem-like Divs: style classes, and the PDF's numbers in their headings.
local function style_theorems(doc, theorems, numbers)
  local numbered_count = 0
  doc:walk({
    Div = function(div)
      local env = theorems[div.classes[1] or ""]
      if env and env.numbered then numbered_count = numbered_count + 1 end
    end
  })
  local use_numbers = numbers and numbered_count == #numbers
  if numbers and not use_numbers then
    quarto.log.warning(string.format("note reader: %d theorem blocks but %d numbers", numbered_count, #numbers))
  end

  local index = 0
  return doc:walk({
    traverse = "topdown",
    Div = function(div)
      local name = div.classes[1] or ""
      local env = theorems[name]
      if env then
        div.classes:insert("note-theorem")
        div.classes:insert("note-theorem--" .. env.style)
        if env.numbered then
          index = index + 1
          local first = div.content[1]
          local lead = first and (first.t == "Para" or first.t == "Plain") and first.content[1]
          if use_numbers and lead and lead.t == "Strong" then
            lead.content = { pandoc.Str(env.title), pandoc.Space(), pandoc.Str(numbers[index]) }
          end
        end
      elseif name == "proof" then
        div.classes:insert("note-proof")
      end
      return div
    end
  })
end

local function style_boxes(doc, boxes)
  return doc:walk({
    Div = function(div)
      local name = div.classes[1] or ""
      local title = boxes[name]
      if title == nil and name ~= "tcolorbox" then return nil end
      div.classes:insert("note-box")
      if title and title ~= "" then
        div.content:insert(1, pandoc.Div({ pandoc.Plain({ pandoc.Str(title) }) }, pandoc.Attr("", { "note-box-title" })))
      end
      return div
    end
  })
end

local function reference_name(label, theorems, plural)
  local env = theorems[label.type or ""]
  local name = env and env.title or REFERENCE_NAMES[label.type or ""] or ""
  if plural and name ~= "" then
    name = name:gsub("%.$", "") .. (name:match("%.$") and "s." or "s")
  end
  return name
end

local function format_number(label)
  if label.type == "equation" then return "(" .. label.number .. ")" end
  return label.number
end

-- \ref, \eqref, \cref, and \Cref links, written as the PDF prints them.
local function resolve_references(doc, labels, theorems)
  return doc:walk({
    Link = function(link)
      local kind = link.attributes["reference-type"]
      local keys = link.attributes["reference"]
      if not kind or not keys then return nil end

      local found = {}
      for key in keys:gmatch("[^,%s]+") do
        if labels[key] and labels[key].number then table.insert(found, labels[key]) end
      end
      if #found == 0 then return nil end

      local function join(items)
        if #items == 1 then return items[1] end
        return table.concat(items, ", ", 1, #items - 1) .. " and " .. items[#items]
      end

      local named = kind == "ref+label" or kind == "ref+Label"
      local same_type = true
      for _, label in ipairs(found) do
        if label.type ~= found[1].type then same_type = false end
      end

      local parts = {}
      for _, label in ipairs(found) do
        local number = kind == "ref" and label.number or format_number(label)
        if kind == "eqref" and label.type ~= "equation" then number = "(" .. label.number .. ")" end
        if named and not same_type then
          local name = reference_name(label, theorems, false)
          number = name ~= "" and (name .. " " .. number) or number
        end
        table.insert(parts, number)
      end

      -- Like cleveref: "Definitions 1.4 and 1.6", or "Theorem 1.20 and Definition 1.22".
      local text = join(parts)
      if named and same_type then
        local name = reference_name(found[1], theorems, #found > 1)
        if name ~= "" then text = name .. " " .. text end
      end
      link.content = { pandoc.Str(text) }
      return link
    end
  })
end

-- Equation numbers as MathJax \tag{}s, anchors for labelled equations, and
-- macros MathJax lacks.
local function prepare_math(doc, labels)
  local function rewrite(text)
    for _, rule in ipairs(MATH_REWRITES) do text = text:gsub(rule[1], rule[2]) end
    text = text:gsub("\\eqref%s*{([^}]*)}", function(key)
      local label = labels[key]
      return label and label.number and ("\\text{(" .. label.number .. ")}") or "\\text{(?)}"
    end)
    text = text:gsub("\\c?ref%s*{([^}]*)}", function(key)
      local label = labels[key]
      return label and label.number and ("\\text{" .. label.number .. "}") or "\\text{?}"
    end)
    return text
  end

  return doc:walk({
    Math = function(math)
      math.text = rewrite(math.text)
      if math.mathtype ~= "DisplayMath" then return math end

      local ids = {}
      math.text = math.text:gsub("\\label%s*{([^}]*)}", function(key)
        table.insert(ids, key)
        local label = labels[key]
        if label and label.type == "equation" and label.number then
          return "\\tag{" .. label.number .. "}"
        end
        return ""
      end)
      if #ids == 0 then return math end

      local wrapped = pandoc.Span({ math }, pandoc.Attr(ids[1], { "note-equation" }))
      local inlines = {}
      for i = 2, #ids do table.insert(inlines, pandoc.Span({}, pandoc.Attr(ids[i]))) end
      table.insert(inlines, wrapped)
      return inlines
    end
  })
end

-- Figures that did not compile point to the PDF instead.
local function fallback_figures(doc, ready, pdf)
  return doc:walk({
    Image = function(image)
      if not image.src:match("^figures/fig%-%d+%.svg$") then return nil end
      if ready then
        image.classes:insert("note-latex-figure")
        return image
      end
      local message = { pandoc.Str("Figure available in the PDF") }
      if pdf then
        return pandoc.Link(message, pdf, "", pandoc.Attr("", { "note-figure-missing" }))
      end
      return pandoc.Span(message, pandoc.Attr("", { "note-figure-missing" }))
    end
  })
end

local function read_latex(page)
  local folder = note_folder()
  local work = pandoc.path.join({ quarto.project.directory, "_generated", "latex-notes", pandoc.path.filename(folder) })
  local tex = read_file(pandoc.path.join({ work, "web.tex" }))
  if not tex then
    quarto.log.warning("note reader: run scripts/build-note-sources.mjs to prepare " .. folder)
    return pandoc.Pandoc({ pandoc.Para({ pandoc.Str("This note has not been prepared for the web yet.") }) })
  end
  local meta = quarto.json.decode(read_file(pandoc.path.join({ work, "meta.json" })) or "{}")
  local theorems = meta.theorems or {}

  local doc = pandoc.read(tex, "latex")
  doc = normalize_levels(doc)
  doc = number_sections(doc, meta.sections)
  doc = style_theorems(doc, theorems, meta.environments)
  doc = style_boxes(doc, meta.boxes or {})
  doc = resolve_references(doc, meta.labels or {}, theorems)
  doc = prepare_math(doc, meta.labels or {})
  doc = fallback_figures(doc, meta.figuresReady, page.pdf)
  return doc
end

-- ---------------------------------------------------------------------------
-- Page layout

local function render_toc(entries)
  local html = {
    '<nav class="note-toc" aria-label="Contents">',
    '<details class="note-toc-details" open>',
    '<summary class="note-toc-title">Contents</summary>',
    '<ol class="note-toc-list">'
  }
  local group_open = false
  local sublist_open = false

  for _, entry in ipairs(entries) do
    local link = string.format('<a href="#%s" data-target="%s">%s</a>', entry.id, entry.id, entry.label)
    if entry.level == 2 then
      if sublist_open then table.insert(html, "</ol>") end
      if group_open then table.insert(html, "</li>") end
      table.insert(html, '<li class="note-toc-group">' .. link)
      group_open, sublist_open = true, false
    else
      if not sublist_open then
        table.insert(html, '<ol class="note-toc-sublist">')
        sublist_open = true
      end
      table.insert(html, "<li>" .. link .. "</li>")
    end
  end

  if sublist_open then table.insert(html, "</ol>") end
  if group_open then table.insert(html, "</li>") end
  table.insert(html, "</ol></details></nav>")
  return table.concat(html, "\n")
end

function Pandoc(doc)
  local page = load_page_data()
  local source = doc.meta["note-source"] and pandoc.utils.stringify(doc.meta["note-source"])
  if not source then return doc end

  local note
  if source:match("%.tex$") then
    note = read_latex(page)
  else
    local markdown = read_file(pandoc.path.join({ pandoc.path.directory(quarto.doc.input_file), source }))
    note = pandoc.read(markdown or "", "markdown")
    note.blocks = merge_figure_captions(note.blocks)
  end

  local body = {}
  local toc = {}
  local fallback_title = nil
  local skip_level = nil

  for _, block in ipairs(note.blocks) do
    if block.t == "Header" and skip_level and block.level <= skip_level then
      skip_level = nil
    end

    if skip_level then
      -- Inside the note's hand-written contents list; the generated TOC replaces it.
      -- Raw HTML (anchors such as <a id="lecture-1">) is kept so links still resolve.
      if is_raw_html(block) then table.insert(body, block) end
    elseif block.t == "Header" and block.level == 1 and not fallback_title then
      -- The note's own H1 becomes the page header title.
      fallback_title = block.content
    elseif block.t == "Header" and CONTENTS_HEADINGS[pandoc.utils.stringify(block.content):lower()] then
      skip_level = block.level
    else
      if block.t == "Header" and TOC_LEVELS[block.level] and block.identifier ~= "" then
        table.insert(toc, { level = block.level, id = block.identifier, label = inlines_to_html(block.content) })
      end
      if block.t == "Table" then
        block = pandoc.Div({ block }, pandoc.Attr("", { "note-table" }))
      end
      table.insert(body, block)
    end
  end

  local header = page.header
  if not header then
    local title = fallback_title and inlines_to_html(fallback_title) or "Study Notes"
    header = string.format(
      '<header class="note-reader-header"><a class="note-reader-back" href="%s/notes.html"><span aria-hidden="true">←</span> Study Notes</a>' ..
      '<div class="note-reader-heading"><div class="note-reader-heading-text"><h1 class="section-title note-reader-title page-first-title">%s</h1></div></div></header>',
      quarto.project.offset, title
    )
  end

  if page.pagetitle then doc.meta.pagetitle = page.pagetitle end
  if page.description then doc.meta["description-meta"] = page.description end

  local layout = { pandoc.Div(body, pandoc.Attr("", { "note-article" })) }
  if #toc > 0 then table.insert(layout, 1, pandoc.RawBlock("html", render_toc(toc))) end

  doc.blocks = {
    pandoc.Div({
      pandoc.RawBlock("html", header),
      pandoc.Div(layout, pandoc.Attr("", { "note-reader-layout" }))
    }, pandoc.Attr("", { "site-shell", "note-reader" }, { ["aria-label"] = "Study note" })),
    pandoc.RawBlock("html", string.format('<script src="%s/assets/js/note-reader.js"></script>', quarto.project.offset))
  }
  return doc
end
